import Foundation
import Testing
@testable import UltraViewerProtocol

private func directHex(_ text: String) -> Data {
    let bytes = Array(text.utf8)
    return Data(stride(from: 0, to: bytes.count, by: 2).map {
        UInt8(String(decoding: bytes[$0..<$0+2], as: UTF8.self), radix: 16)!
    })
}

@Test func directFrameEncryptsTheFormatByteBeforeLengthFraming() throws {
    let codec = try TCPDirectPeerCodec(encryptionKey: "password")
    let envelope = DirectPeerEnvelope(formatFlag: true, payload: Data([0x48,0,0x69,0]))
    // Independently generated by OpenSSL AES256-CBC, using the checked key-copy
    // overlap and IV000102...0f. No Windows peer or credential was used.
    let expected = directHex("20000000000102030405060708090a0b0c0d0e0f8ee36820538aebf76ccad1f1fe63df42")
    #expect(try codec.encode(envelope, iv: Data(0..<16)) == expected)
    #expect(try codec.decodeFrame(Data(expected.dropFirst(4))) == envelope)
    // Neither the flag nor the relay kind/address/port is outside encryption.
    #expect(expected.prefix(4) == Data([32,0,0,0]))
}

@Test func directCodecNeverRetriesMalformedPacketsAsPlaintext() throws {
    let codec = try TCPDirectPeerCodec(encryptionKey: "fixture-only")
    #expect(throws: (any Error).self) { try codec.decodeFrame(Data([0,1,2,3])) }
    #expect(throws: (any Error).self) {
        try codec.decodeFrame(DirectPeerEnvelope(formatFlag: false, payload: Data("0".utf8)).encode())
    }
    let emptyPlaintext = try LegacyAES(password: "fixture-only").encrypt(Data(), iv: Data(0..<16))
    #expect(throws: DirectPeerEnvelope.Error.emptyEnvelope) { try codec.decodeFrame(emptyPlaintext) }
    #expect(throws: TCPDirectPeerTransport.Error.invalidKey) { try TCPDirectPeerCodec(encryptionKey: "") }
}

@Test func directCoalescedEncryptedFramesRetainEachFlagAndPayload() throws {
    let codec = try TCPDirectPeerCodec(encryptionKey: "fixture-only")
    let messages = [DirectPeerEnvelope(formatFlag: false, payload: Data([30,0,1,2])),
                    DirectPeerEnvelope(formatFlag: true, payload: Data("chat".utf8))]
    let wire = try messages.reduce(into: Data()) { $0.append(try codec.encode($1)) }
    var framing = LengthPrefixedFrame.Decoder(maximumPayloadLength: 4096)
    var decoded: [DirectPeerEnvelope] = []
    for byte in wire {
        for frame in try framing.append(Data([byte])) { decoded.append(try codec.decodeFrame(frame)) }
    }
    #expect(decoded == messages)
    #expect(!framing.hasIncompleteFrame)
}

@Test func lanDirectOnlyUsesCorrelatedPrivateAddressesOnSamePublicIP() throws {
    let ownPublic = try RelayIPv4Address("203.0.113.7")
    func peer(_ publicIP: String = "203.0.113.7", _ details: String? = "192.168.1.120|49715") -> RelayIPv4Address? {
        LANDirectUpgradeState.peerLANAddress(publicAddress: publicIP, ownPublicAddress: ownPublic,
            details: details, fallbackAddress: "10.1.2.3")
    }
    #expect(peer() == (try RelayIPv4Address("192.168.1.120")))
    #expect(peer("203.0.113.8") == nil)
    for malformed in ["192.168.1.120|0", "192.168.1.120|65536", "192.168.1.120|123|key",
                       "203.0.113.8|123", "127.0.0.1|123", "0.0.0.0|123", "host.local|123"] {
        #expect(peer("203.0.113.7", malformed) == nil)
    }
    #expect(peer("203.0.113.7", nil) == (try RelayIPv4Address("10.1.2.3")))
    #expect(TCPDirectPeerTransport.isLANAddress(try RelayIPv4Address("172.31.2.3")))
    #expect(!TCPDirectPeerTransport.isLANAddress(try RelayIPv4Address("172.32.2.3")))
}

@Test func directSelectionRequiresSourceThenWrittenLoginThenInitialization() throws {
    let expected = try RelayIPv4Address("192.168.1.120")
    let other = try RelayIPv4Address("192.168.1.121")
    let id = UUID(), wrong = UUID()
    var state = LANDirectUpgradeState()
    let addedWrong = state.connected(wrong, address: other)
    let addedExpected = state.connected(id, address: expected)
    #expect(addedWrong)
    #expect(addedExpected)
    let beforeLookup = state.beginLogin()
    #expect(beforeLookup == nil) // Lookup has not correlated the source.
    let rejected = state.expect(expected)
    #expect(rejected == [wrong])
    let loginCandidate = state.beginLogin()
    #expect(loginCandidate == id)
    #expect(!state.permitsInitialization(from: id))
    let selectedBeforeWrite = state.selectInitialized(id)
    let wrongWriteCompletion = state.markLoginSent(wrong)
    let written = state.markLoginSent(id)
    #expect(!selectedBeforeWrite)
    #expect(!wrongWriteCompletion)
    #expect(written)
    #expect(state.permitsInitialization(from: id))
    #expect(state.selected == nil) // Healthy relay remains selected.
    let selectedWrong = state.selectInitialized(wrong)
    let selectedExpected = state.selectInitialized(id)
    #expect(!selectedWrong)
    #expect(selectedExpected)
    #expect(state.selected == id)
    let addedAfterSelection = state.connected(UUID(), address: expected)
    let removedSelected = state.remove(id)
    #expect(!addedAfterSelection)
    #expect(removedSelected)
    #expect(state.selected == nil)
    #expect(!state.permitsInitialization(from: id))
}

@Test func failedUninitializedDirectCandidateDoesNotReplaceRelay() throws {
    let address = try RelayIPv4Address("10.1.2.3"), id = UUID()
    var state = LANDirectUpgradeState()
    _ = state.expect(address)
    let added = state.connected(id, address: address)
    let loginCandidate = state.beginLogin()
    let written = state.markLoginSent(id)
    let removedSelected = state.remove(id)
    #expect(added)
    #expect(loginCandidate == id)
    #expect(written)
    #expect(!removedSelected) // No authenticated initialization was selected.
    #expect(state.selected == nil)
    #expect(state.loginCandidate == nil)
    #expect(state.candidates.isEmpty)
    let staleCompletion = state.markLoginSent(id)
    #expect(!staleCompletion) // Stale send-completion cannot reactivate it.
}

@Test(.timeLimit(.minutes(1))) func directNativeLoopbackExchangesOnlyEncryptedApplicationEnvelopes() async throws {
    let listener = TCPDirectPeerTransport(maximumPayloadLength: 4096, allowLoopbackForTesting: true)
    let opened = try await listener.startListener(localAddress: RelayIPv4Address("127.0.0.1"), encryptionKey: "fixture-only")
    let client = FramedTCPTransport(maximumPayloadLength: 4096)
    let replies = try await client.open(host: "127.0.0.1", port: opened.advertisement.port)
    var events = opened.stream.makeAsyncIterator()
    guard case let .connected(id, address)? = try await events.next() else {
        Issue.record("Missing direct accepted event"); await listener.close(); await client.close(); return
    }
    #expect(address == (try RelayIPv4Address("127.0.0.1")))
    let codec = try TCPDirectPeerCodec(encryptionKey: "fixture-only")
    let outgoing = DirectPeerEnvelope(formatFlag: true, payload: Data([0x48,0,0x69,0]))
    let wire = try codec.encode(outgoing)
    try await client.send(Data(wire.dropFirst(4)))
    guard case let .message(receivedID, envelope)? = try await events.next() else {
        Issue.record("Missing encrypted direct message"); await listener.close(); await client.close(); return
    }
    #expect(receivedID == id)
    #expect(envelope == outgoing)
    try await listener.send(Data("18".utf8), to: id)
    var responses = replies.makeAsyncIterator()
    let received = try await responses.next()
    let response = try #require(received)
    #expect(try codec.decodeFrame(response) == DirectPeerEnvelope(formatFlag: false, payload: Data("18".utf8)))
    await listener.close()
    await client.close()
}

@Test func productionDirectListenerRejectsPublicAndLoopbackBinds() async throws {
    for text in ["127.0.0.1", "203.0.113.10", "0.0.0.0"] {
        let listener = TCPDirectPeerTransport()
        do {
            _ = try await listener.startListener(localAddress: RelayIPv4Address(text), encryptionKey: "fixture-only")
            Issue.record("Invalid LAN bind was accepted")
        } catch { #expect(error as? TCPDirectPeerTransport.Error == .invalidLANAddress) }
        await listener.close()
    }
}
